cd . && python3 - <<'EOF'
import re
pat = re.compile(r'^(\S+)\s+(\S+)\s+\[([a-z-]+)\]\s+(.*?)\s*$')
rows=[]
with open('app.log') as f:
    for i,line in enumerate(f,1):
        line=line.rstrip('\n')
        m=pat.match(line)
        if not m:
            print("NOMATCH", i, line); continue
        ts, lvl, svc, msg = m.groups()
        kv = dict(re.findall(r'(\w+)=([^\s]+)', msg))
        rows.append((i,ts,lvl,svc,msg,kv))
print("total", len(rows))
# 5xx per service
from collections import Counter, defaultdict
c=Counter()
first={}; last={}
for i,ts,lvl,svc,msg,kv in rows:
    if 'status' in kv:
        try: st=int(kv['status'])
        except: continue
        if st>=500:
            c[svc]+=1
            if svc not in first: first[svc]=(i,ts,line)
            last[svc]=(i,ts)
print(c)
for k,v in first.items(): print("FIRST",k,v)
for k,v in last.items(): print("LAST",k,v)
EOF
